import numpy as np

def remove_baseline(x, fs, win_s):
    x = np.asarray(x, float)
    w = int(win_s * fs)
    if w % 2 == 0:
        w += 1
    r = (w - 1) // 2
    xp = np.pad(x, r, mode="edge")
    base = np.median(np.lib.stride_tricks.sliding_window_view(xp, w), axis=1)
    return (x - base).tolist()
